  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Healthy Relationships and Communication$j$, $j${"readings": [{"title": "Proverbs 13 (King James Version)", "url": "/portal/bible/Proverbs/13"}], "body": "Relationships with family, friends, church, teachers and eventually a spouse shape your health. Healthy relationships include respect, honesty, trust, kindness, healthy boundaries and shared values. Unhealthy relationships include control, pressure, disrespect, jealousy and secrecy. Proverbs 13:20 says, He that walketh with wise men shall be wise: but a companion of fools shall be destroyed.\n\nGood communication has three parts. Listen fully without interrupting. Use I statements, such as I feel hurt when plans change without warning, instead of blaming. Ask questions to understand. James 1:19 says, let every man be swift to hear, slow to speak, slow to wrath. Body language and tone also send messages. Conflict is normal. Solve it by staying calm, agreeing on the problem, listening to each side, suggesting solutions and choosing one together. Sometimes you must walk away and ask a trusted adult to help.\n\nBoundaries are limits that protect you. Healthy boundaries cover time, privacy, physical space and what you will and will not do. Say them clearly and kindly, and respect the boundaries of others. Peer pressure is influence from people your age, and it can be positive or negative. Choose friends who help you become your best self.\n\nWorked example: a friend keeps borrowing money and forgetting to repay. Say, I feel stressed when money is not returned, so I will not lend any more. Common mistake: staying silent until you explode.\n\nYour task: (1) List four qualities of a healthy relationship. (2) Write an I statement for a real conflict. (3) Write a boundary you want to keep.\n\nFlorida standards: HE.912.C.2, HE.912.B.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.2, HE.912.B.4", "script": "Welcome back. Listen, the relationships in your life help shape your health.\n\nHealthy relationships include respect, honesty, trust, kindness and healthy boundaries. Unhealthy relationships include control, pressure, disrespect and secrecy. Proverbs 13:20 says, He that walketh with wise men shall be wise.\n\nNow watch this. Good communication has three parts. Listen fully without interrupting. Use I statements, like I feel hurt when plans change without warning, instead of blaming. Ask questions to understand. James 1:19 says, let every man be swift to hear, slow to speak, slow to wrath.\n\nConflict is normal. Stay calm, agree on the problem, listen to each side, suggest solutions and choose one together. Sometimes you must walk away and ask a trusted adult for help.\n\nBoundaries are limits that protect you. Say them clearly and kindly, and respect the limits of others. Peer pressure can be positive or negative, so choose friends who help you become your best.\n\nYour task is to list four qualities of a healthy relationship, write an I statement and write a boundary. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Healthy Relationships and Communication$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Abstinence, Sexual Health and Respect$j$, $j${"readings": [{"title": "Proverbs 4 (King James Version)", "url": "/portal/bible/Proverbs/4"}], "body": "God designed marriage as a lifelong union between a man and a woman, and sexual intimacy as a gift for marriage. Hebrews 13:4 says, Marriage is honourable in all, and the bed undefiled: but whoremongers and adulterers God will judge. Proverbs 4:23 says, Keep thy heart with all diligence; for out of it are the issues of life. In Florida, schools teach that abstinence from sexual activity outside of marriage is the expected standard for school age children and the only certain way to avoid pregnancy and sexually transmitted infections.\n\nTeens are changing physically, emotionally and socially. These changes are normal. Choosing abstinence is a decision about your future, your health and your relationship with God. Skills that support it: set personal standards ahead of time, avoid situations that lead to pressure, choose friends with shared values, set limits on technology and dating, and have a plan to leave or call a trusted adult.\n\nRespect and consent: no one has a right to pressure, force or manipulate another person. Another person cannot give consent if they are underage, afraid, impaired or pressured. Sexual abuse and assault are crimes, and they are never the victim's fault. If someone touches you or pressures you in a way that feels wrong, say no, get away, and tell a trusted adult. You can also contact a school counselor or law enforcement. Help is available.\n\nQuestions about reproductive health belong in conversations with your parents or guardians and a doctor, who can provide medical information suited to your age and needs. Pornography and sexting harm minds and relationships, can be illegal for minors, and are best avoided.\n\nWorked example: before a date, decide your limits, plan a group activity and agree on a way to check in. Common mistake: waiting until pressure appears to decide your standards.\n\nYour task: (1) Write three personal standards. (2) Explain what consent means and who to tell if someone pressures you. (3) List two ways to avoid risky situations.\n\nFlorida standards: HE.912.C.1, HE.912.C.2, HE.912.B.5, HE.912.B.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.C.1, HE.912.C.2, HE.912.B.5, HE.912.B.6", "script": "Welcome back. Listen, this lesson is about honor, respect and protecting your future.\n\nGod designed marriage as a lifelong union between a man and a woman, and sexual intimacy as a gift for marriage. Hebrews 13:4 says, Marriage is honourable in all, and the bed undefiled. Proverbs 4:23 says, Keep thy heart with all diligence; for out of it are the issues of life. In Florida, schools teach that abstinence outside of marriage is the expected standard and the only certain way to avoid pregnancy and sexually transmitted infections.\n\nNow watch this. Teen changes are normal. Choosing abstinence is a decision about your future. Set your standards ahead of time. Avoid situations that lead to pressure. Choose friends with shared values. Set limits on technology and dating. Have a plan to leave or call a trusted adult.\n\nRespect and consent matter. No one has a right to pressure, force or manipulate you. If someone touches you or pressures you in a way that feels wrong, say no, get away and tell a trusted adult. Abuse is never the victim's fault.\n\nTake questions about your health to your parents and a doctor. Pornography and sexting harm minds and relationships.\n\nYour task is to write three standards, explain consent and list two ways to avoid risky situations. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Abstinence, Sexual Health and Respect$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Decision Making, Goals and Refusal Skills$j$, $j${"readings": [{"title": "Proverbs 1 (King James Version)", "url": "/portal/bible/Proverbs/1"}], "body": "Every day you make decisions that affect your health. A decision making model gives you steps. One model is DECIDE: Define the problem, list Every choice, Consider the results of each, Identify your values, Decide and act, then Evaluate. Your values, such as faith, family and honesty, guide the best choice. Proverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going.\n\nGoals give direction. A SMART goal is Specific, Measurable, Achievable, Relevant and Time bound. For example, I will walk thirty minutes on five days each week for the next month. Write your goal, plan the steps, ask someone to hold you accountable and track progress. Celebrate small wins and adjust if needed.\n\nRefusal skills help you say no when something is wrong. Use a clear voice: Say no, give a reason, suggest an alternative and leave. Use humor, repeat your answer or blame a rule if needed. You do not owe anyone a long explanation. 2 Timothy 1:7 says, For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.\n\nThink about influences on your choices: family, friends, culture, media, advertising and technology. Ask who benefits when you accept a message.\n\nWorked example: you are invited to a party where alcohol will be served. Define the problem, list options (go, skip, suggest another plan), consider risks, check values, decide, and tell a parent. Common mistake: deciding quickly without considering results.\n\nYour task: (1) Apply the DECIDE steps to a real teen problem. (2) Write a SMART health goal. (3) Write a refusal script.\n\nFlorida standards: HE.912.B.5, HE.912.B.6, HE.912.B.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.B.5, HE.912.B.6, HE.912.B.4", "script": "Welcome back. Listen, your life is the sum of your decisions. Proverbs 14:15 says, the prudent man looketh well to his going.\n\nHere is a decision model called DECIDE. Define the problem. List every choice. Consider the results of each. Identify your values. Decide and act. Evaluate. Your values, like faith, family and honesty, guide the best choice.\n\nNow watch this. Goals give direction. A SMART goal is Specific, Measurable, Achievable, Relevant and Time bound. For example, I will walk thirty minutes on five days each week for a month. Write it down, plan the steps, ask someone to keep you accountable and track your progress.\n\nRefusal skills help you say no. Say no, give a reason, suggest an alternative and leave. You do not owe anyone a long explanation. Second Timothy 1:7 says, God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.\n\nThink about influences on your choices: family, friends, media and advertising. Ask who benefits.\n\nYour task is to apply DECIDE to a real teen problem, write a SMART goal and write a refusal script. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Decision Making, Goals and Refusal Skills$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Health Information, Advocacy and Lifelong Wellness$j$, $j${"readings": [{"title": "1 Thessalonians 5 (King James Version)", "url": "/portal/bible/1Thessalonians/5"}], "body": "Not all health information is true. Before you trust a source, check who wrote it, whether the author has medical training, when it was published, whether claims are supported by evidence and whether someone is selling something. Reliable sources include doctors, nurses and pharmacists, hospitals, the Centers for Disease Control and Prevention, the National Institutes of Health, the American Academy of Pediatrics and university medical sites. Be careful with social media posts, influencers, miracle cures and sites that end in advertisements. 1 Thessalonians 5:21 says, Prove all things; hold fast that which is good.\n\nKnowing how to use health care is a life skill. A primary care doctor handles checkups and common illnesses, specialists treat particular problems, urgent care handles non life threatening problems, and an emergency room handles serious emergencies. Teens benefit from yearly checkups, dental visits, vision checks and vaccines. Keep a list of your medicines and allergies with a parent. Read labels and take medicine only as directed. Health insurance helps pay for care, and families can ask about community clinics if cost is a concern.\n\nAdvocacy means speaking up for health. You can advocate by sharing accurate information, helping at a church health fair, supporting a friend who needs help, volunteering, or writing a message to a leader about a health need. Galatians 6:2 says, Bear ye one another's burdens, and so fulfil the law of Christ.\n\nLifelong wellness comes from steady habits: balanced food, activity, sleep, healthy relationships, regular checkups, prayer and service.\n\nWorked example: you see a post claiming a pill cures anything. Check the author, look for the same claim at the CDC or a doctor's site, and ask a parent. Common mistake: sharing a claim before checking it.\n\nYour task: (1) Evaluate a health claim using four questions. (2) Name where you would go for a checkup, an urgent problem and an emergency. (3) Plan one act of health advocacy.\n\nFlorida standards: HE.912.B.3, HE.912.P.8, HE.912.B.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "HE.912.B.3, HE.912.P.8, HE.912.B.6", "script": "Welcome back. Listen, not everything you read about health is true. First Thessalonians 5:21 says, Prove all things; hold fast that which is good.\n\nBefore you trust a source, check who wrote it, whether the author has medical training, when it was published, whether the claim has evidence and whether someone is selling something. Reliable sources include doctors, nurses and pharmacists, hospitals, the CDC, the National Institutes of Health and the American Academy of Pediatrics. Be careful with influencers, miracle cures and posts that end in advertisements.\n\nNow watch this. Know how to use health care. A primary care doctor handles checkups and common illness. Urgent care handles problems that are not life threatening. The emergency room handles serious emergencies. Teens benefit from yearly checkups, dental visits and vision checks. Take medicine only as directed.\n\nAdvocacy means speaking up for health. Share accurate information, help at a church health fair, support a friend or volunteer. Galatians 6:2 says, Bear ye one another's burdens.\n\nLifelong wellness comes from steady habits: food, activity, sleep, healthy relationships, checkups, prayer and service.\n\nYour task is to evaluate a health claim, match problems to the right care and plan one act of advocacy. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Health Information, Advocacy and Lifelong Wellness$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Relationships and Choices$j$, $j${"prompt": "Write a report of at least 250 words on relationships, decisions and wellness. Use complete sentences and label each part. Do not include private details about yourself or others. Proverbs 4:23 says, Keep thy heart with all diligence; for out of it are the issues of life.\n\nPart 1: Describe a healthy relationship and write an I statement and a boundary.\nPart 2: Explain why you choose abstinence or support it, what consent means, and who you would tell if someone pressured you.\nPart 3: Apply the DECIDE model to a real teen decision and write a SMART goal.\nPart 4: Explain how you will check whether health information is reliable and where you would go for a checkup, an urgent problem and an emergency.\nPart 5: Explain how Scripture guides your relationships and choices.", "rubric": "100 points. Part 1: 20 points. Part 2: 25 points. Part 3: 20 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Relationships and Choices$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Guarding the Heart$j$, $j${"prompt": "Write a post of at least 120 words that (1) names one standard you will keep in your relationships, (2) explains how friends, media or technology can challenge it, (3) describes a plan to keep it and a trusted adult who can help, and (4) connects your answer to Proverbs 4:23 or 2 Timothy 1:7. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it wise to decide your standards before you are pressured? Do not share private details about yourself or others."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Guarding the Heart$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Healthy Relationships and Communication$j$, $j${"questions": [{"q": "Which is a quality of a healthy relationship?", "options": ["Secrecy", "Control", "Respect and honesty", "Pressure"]}, {"q": "An I statement:", "options": ["Ends the talk", "Shouts", "Blames the other person", "Describes your feelings without blaming"]}, {"q": "A boundary is:", "options": ["A secret", "A wall that ends all friendship", "A limit that protects you", "A punishment"]}, {"q": "James 1:19 says to be swift to:", "options": ["Hear", "Wrath", "Judge", "Speak"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Healthy Relationships and Communication$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,0}'::int[], array[$j$Healthy relationships rest on respect and honesty.$j$,$j$I statements reduce conflict.$j$,$j$Boundaries protect people.$j$,$j$Be swift to hear and slow to speak.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Healthy Relationships and Communication$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Abstinence, Sexual Health and Respect$j$, $j${"questions": [{"q": "When is the best time to decide your personal standards?", "options": ["During pressure", "Before pressure appears", "After a mistake", "Never"]}, {"q": "Abstinence is the only certain way to avoid:", "options": ["Pregnancy and sexually transmitted infections", "Homework", "Exercise", "Friendship"]}, {"q": "Who is at fault when abuse happens?", "options": ["No one", "The abuser, never the victim", "The victim", "The friends"]}, {"q": "Where should you take health questions?", "options": ["Parents, guardians and a doctor", "Strangers online", "Social media comments", "Rumors"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Abstinence, Sexual Health and Respect$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,0}'::int[], array[$j$Deciding ahead makes you stronger.$j$,$j$Abstinence prevents both completely when practiced.$j$,$j$Abuse is never the victim's fault.$j$,$j$Trusted adults and doctors give reliable guidance.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Abstinence, Sexual Health and Respect$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Decision Making, Goals and Refusal Skills$j$, $j${"questions": [{"q": "In the DECIDE model, the E at the end stands for:", "options": ["Erase", "Enjoy", "Evaluate", "Escape"]}, {"q": "A SMART goal is:", "options": ["Specific, Measurable, Achievable, Relevant and Time bound", "Secret and short", "Small and silent", "Simple and slow"]}, {"q": "A good refusal includes:", "options": ["A long argument", "A clear no, a reason, an alternative and leaving", "Silence", "A maybe"]}, {"q": "Your values help you:", "options": ["Choose the best option", "Ignore results", "Copy friends", "Avoid all decisions"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Decision Making, Goals and Refusal Skills$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,1,0}'::int[], array[$j$You evaluate the result of your decision.$j$,$j$SMART describes a clear goal.$j$,$j$A simple plan makes saying no easier.$j$,$j$Values guide wise choices.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Decision Making, Goals and Refusal Skills$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Health Information, Advocacy and Lifelong Wellness$j$, $j${"questions": [{"q": "Which is a reliable source of health information?", "options": ["The CDC or a doctor", "An anonymous post", "A rumor", "A product advertisement"]}, {"q": "For a serious emergency, go to:", "options": ["A social media group", "Wait until morning", "The emergency room or call 911", "A coupon site"]}, {"q": "Health advocacy means:", "options": ["Speaking up and acting to support health", "Spreading rumors", "Avoiding doctors", "Hiding problems"]}, {"q": "1 Thessalonians 5:21 says to:", "options": ["Ignore the truth", "Avoid questions", "Prove all things", "Believe everything"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Health Information, Advocacy and Lifelong Wellness$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,2}'::int[], array[$j$Credible sources have training and evidence.$j$,$j$Emergencies need immediate care.$j$,$j$Advocates share accurate information and help others.$j$,$j$Test claims before you accept them.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Health Information, Advocacy and Lifelong Wellness$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Relationships and Choices$j$, $j${"questions": [{"q": "A healthy relationship includes:", "options": ["Respect, honesty and trust", "Pressure", "Secrets that harm", "Control and jealousy"]}, {"q": "In the DECIDE model you first:", "options": ["Evaluate", "Decide", "Ignore", "Define the problem"]}, {"q": "Abstinence until marriage is:", "options": ["Unhealthy", "Required for no one", "A rumor", "The only certain way to avoid pregnancy and sexually transmitted infections"]}, {"q": "Consent cannot be given when a person is:", "options": ["Thoughtful", "Relaxed", "Well rested", "Pressured, afraid, underage or impaired"]}, {"q": "A SMART goal is:", "options": ["Specific and time bound", "Secret", "Vague", "Impossible"]}, {"q": "A reliable health source is:", "options": ["A rumor", "A miracle cure ad", "An unnamed post", "The CDC"]}, {"q": "For a non life threatening problem after hours, you might go to:", "options": ["A game", "A friend", "Urgent care", "A store"]}, {"q": "Proverbs 4:23 tells us to:", "options": ["Follow every feeling", "Ignore our hearts", "Hide from others", "Keep our hearts with diligence"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Relationships and Choices$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,3,3,0,3,2,3}'::int[], array[$j$These qualities build healthy bonds.$j$,$j$D stands for define the problem.$j$,$j$It is the expected standard and fully protective.$j$,$j$These conditions remove true consent.$j$,$j$SMART goals are clear and measurable.$j$,$j$Reliable sources use evidence.$j$,$j$Urgent care fits problems that are not life threatening.$j$,$j$The heart is the source of life's issues.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Relationships and Choices$j$ on conflict (item_id) do nothing;
